    const hw = (f) => hand(f), big = (f) => Math.max(...TS.championOf(TR, f).record.weights.map((v, i) => Math.abs(v - hw(f)[i]))).toFixed(4), cdig = X.digestOf(D.championOf(LAST, "plain").record.weights);
    ok("!! the champion lines of the ledger read word for word (the largest movement computed here by hand from the hand weights, the family padded to 13, the kept count and the training scores to four decimals), then circuit-plain's champion with its digest and the committed one", L.includes(`  station-large champion k 1: 3 weights moved from the start, the largest by ${big("station-large")}; last training score 0.9200 against the start's 0.8600 (+0.0600)`) && L.includes(`  station-small champion k 2: 4 weights moved from the start, the largest by ${big("station-small")}; last training score 0.9200 against the start's 0.8700 (+0.0500)`) && L.includes(`  plain-priced  champion k 0: 2 weights moved from the start, the largest by ${big("plain-priced")}; last training score 0.9200 against the start's 0.8700 (+0.0500)`) && L.includes(`  circuit-plain champion of the decision-circuit round: k 2, digest ${cdig} (committed c916e7f5)`));
